const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekAgoStr = weekAgo.toISOString().slice(0, 10);
const todayStr = now.toISOString().slice(0, 10);

const leads = $input.all().map(i => i.json);

let newThisWeek = 0;
let hotThisWeek = 0;
let emergencyThisWeek = 0;
let bookedThisWeek = 0;
let staleThisWeek = 0;
const sourceCounts = {};

for (const lead of leads) {
  const created = String(lead['Date Created'] || '').slice(0, 10);
  if (created >= weekAgoStr && created <= todayStr) {
    newThisWeek++;
    const temp = (lead['Temperature'] || '').trim();
    if (temp === 'Hot') hotThisWeek++;
    const urgency = (lead['Urgency'] || '').trim();
    if (urgency === 'Emergency') emergencyThisWeek++;
    const source = (lead['Source'] || '').trim() || 'Unknown';
    sourceCounts[source] = (sourceCounts[source] || 0) + 1;
  }

  const status = (lead['Status'] || '').trim();
  const lastContact = String(lead['Last Contact'] || '').slice(0, 10);
  const inWindow = lastContact >= weekAgoStr && lastContact <= todayStr;
  if (status === 'Booked' && inWindow) bookedThisWeek++;
  if (status === 'Stale' && inWindow) staleThisWeek++;
}

const bookingRatio = newThisWeek > 0 ? Math.round((bookedThisWeek / newThisWeek) * 100) : 0;
const topSources = Object.entries(sourceCounts).sort((a, b) => b[1] - a[1]).slice(0, 2);
const sourceText = topSources.length ? topSources.map(([s, c]) => s + ' ' + c).join(', ') : 'n/a';

// Owner phone — synced from workflow 04 (Build Alert Message) / workflow 07 (Build Pipeline Digest)
const OWNER_PHONE = '+18575261499';

let msg = 'Weekly Report - Valfin Tech (' + weekAgoStr + ' to ' + todayStr + ')\n';
msg += 'New leads: ' + newThisWeek + ' (Hot ' + hotThisWeek + ', Emergency ' + emergencyThisWeek + ')\n';
msg += 'Booked: ' + bookedThisWeek + ' | Stale: ' + staleThisWeek + ' | Bookings/New ratio: ' + bookingRatio + '%\n';
msg += 'Top sources: ' + sourceText;

return [{ json: {
  reportMessage: msg.trim(),
  ownerPhone: OWNER_PHONE,
  windowStart: weekAgoStr,
  windowEnd: todayStr,
  newThisWeek,
  hotThisWeek,
  emergencyThisWeek,
  bookedThisWeek,
  staleThisWeek,
  bookingRatio,
  sourceCounts
} }];
